"""Deploy targets plan without touching a platform, and a client can add its own (generated by adk_v2/6.0.0)."""

import importlib.util
from pathlib import Path
from typing import ClassVar

import pytest
import yaml

from retail_kyc_onboarding._engine.deploy import (
    DeployPlan,
    DeployProject,
    DeployTarget,
    register_target,
    target,
    target_names,
)

ROOT = Path(__file__).resolve().parents[2]
_spec = importlib.util.spec_from_file_location("deploy_cli", ROOT / "deployment" / "deploy.py")
assert _spec and _spec.loader
deploy = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(deploy)


def test_the_built_in_targets_are_registered():
    """Container, Kubernetes, ADK's own deploy commands and the placeholders are all listed."""
    names = target_names()
    for name in ("docker", "kubernetes", "cloud_run", "gke", "agent_engine", "openshift", "aws_ecs", "azure_container_apps"):
        assert name in names and names[name]


def test_docker_writes_a_dockerfile_for_the_run_host(tmp_path: Path):
    """By default the image runs the governed run host as a non-root user; ADK's API is an opt-in with a warning."""
    plan = target("docker", {"image": "kyc:1"}).plan(deploy.project(), tmp_path)
    text = plan.files["Dockerfile"]
    assert "retail_kyc_onboarding.server:create_run_host" in text and "USER app" in text
    adk = target("docker", {"image": "kyc:1", "entrypoint": "adk"}).plan(deploy.project(), tmp_path)
    assert "retail_kyc_onboarding.server:app" in adk.files["Dockerfile"] and any("no authentication" in n for n in adk.notes)
    ignored = set(plan.files["Dockerfile.dockerignore"].splitlines())
    assert {"**/.env", "**/.venv"} <= ignored
    assert plan.commands == [["docker", "build", "-f", str(tmp_path / "Dockerfile"), "-t", "kyc:1", str(deploy.AGENT_DIR)]]


def test_kubernetes_renders_manifests_and_runs_nothing(tmp_path: Path):
    """A Deployment and a Service with health probes; the target never applies them."""
    plan = target("kubernetes", {"image": "kyc:1", "namespace": "agents"}).plan(deploy.project(), tmp_path)
    docs = list(yaml.safe_load_all(plan.files["kubernetes.yaml"]))
    assert [d["kind"] for d in docs] == ["Deployment", "Service"]
    container = docs[0]["spec"]["template"]["spec"]["containers"][0]
    assert container["image"] == "kyc:1" and container["readinessProbe"]["httpGet"]["path"] == "/readyz"
    assert plan.commands == []


def test_google_targets_delegate_to_adk_deploy(tmp_path: Path):
    """cloud_run, gke and agent_engine hand the agent folder to `adk deploy`."""
    plan = target("cloud_run", {"project": "p", "region": "europe-west1"}).plan(deploy.project(), tmp_path)
    assert plan.commands[0][:3] == ["adk", "deploy", "cloud_run"]
    assert plan.commands[0][-1] == str(deploy.AGENT_DIR)


@pytest.mark.parametrize("name", ["cloud_run", "gke"])
def test_adk_deploy_keeps_paused_runs_in_the_session_database(tmp_path: Path, name: str):
    """ADK's default for `adk deploy` is in-memory sessions, which lose a paused review; the plan says so until a database is set."""
    bare = target(name, {"project": "p", "region": "r"}).plan(deploy.project(), tmp_path)
    assert "--session_service_uri" not in bare.commands[0] and any("paused review is lost" in n for n in bare.notes)
    uri = "postgresql+asyncpg://kyc@db/sessions"
    plan = target(name, {"project": "p", "region": "r", "session_service_uri": uri}).plan(deploy.project(), tmp_path)
    flags = plan.commands[0]
    assert flags[flags.index("--session_service_uri") + 1] == uri and not any("paused review is lost" in n for n in plan.notes)


def test_a_placeholder_explains_what_to_build(tmp_path: Path):
    """A placeholder refuses to plan and says how to replace it."""
    with pytest.raises(NotImplementedError, match="register_target"):
        target("openshift").plan(deploy.project(), tmp_path)


def test_a_dry_run_writes_files_and_runs_nothing(tmp_path: Path, monkeypatch: pytest.MonkeyPatch):
    """Without --apply the command line writes the target's files and starts no process."""
    monkeypatch.setattr("subprocess.run", lambda *a, **k: pytest.fail("a dry run must not run commands"))
    assert deploy.main(["docker", "--out", str(tmp_path)]) == 0
    assert (tmp_path / "Dockerfile").is_file()


def test_a_client_target_can_be_registered(tmp_path: Path):
    """A DeployTarget subclass registered with register_target is found by name."""

    @register_target
    class Echo(DeployTarget):
        name: ClassVar[str] = "echo_test"  # type: ignore[misc]

        def plan(self, project: DeployProject, out: Path) -> DeployPlan:
            return DeployPlan(self.name, files={"hello.txt": project.package})

    assert target("echo_test").plan(deploy.project(), tmp_path).files == {"hello.txt": "retail_kyc_onboarding"}
